def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Detect collinear same-color runs, extending each run at both ends.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg: continue
            for dr, dc in ((1, 1), (1, -1)):
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
